using namespace std;

class Solution {
    vector<int> digits;
    long long memo[20][2][2][2];

    long long dfs(int idx, int carry, bool active_a, bool active_b) {
        if (idx == (int)digits.size()) {
            return carry == 0 ? 1 : 0;
        }
        if (memo[idx][carry][active_a][active_b] != -1) {
            return memo[idx][carry][active_a][active_b];
        }
        int target = digits[idx];
        long long ans = 0;
        int min_a = (active_a && idx == 0) ? 1 : 0;
        int max_a = active_a ? 9 : 0;
        int min_b = (active_b && idx == 0) ? 1 : 0;
        int max_b = active_b ? 9 : 0;
        for (int da = min_a; da <= max_a; ++da) {
            bool next_a = active_a && (da > 0);
            for (int db = min_b; db <= max_b; ++db) {
                bool next_b = active_b && (db > 0);
                int tot = da + db + carry;
                if (tot % 10 == target) {
                    ans += dfs(idx + 1, tot / 10, next_a, next_b);
                }
            }
        }
        return memo[idx][carry][active_a][active_b] = ans;
    }
