import java.util.*;

class Solution {
    private List<Integer> digits = new ArrayList<>();
    private Long[][][][] memo;

    private long dfs(int idx, int carry, int actA, int actB) {
        if (idx == digits.size()) {
            return carry == 0 ? 1 : 0;
        }
        if (memo[idx][carry][actA][actB] != null) {
            return memo[idx][carry][actA][actB];
        }
        int target = digits.get(idx);
        long ans = 0;
        int minA = (actA == 1 && idx == 0) ? 1 : 0;
        int maxA = actA == 1 ? 9 : 0;
        int minB = (actB == 1 && idx == 0) ? 1 : 0;
        int maxB = actB == 1 ? 9 : 0;
        for (int da = minA; da <= maxA; da++) {
            int nextA = (actA == 1 && da > 0) ? 1 : 0;
            for (int db = minB; db <= maxB; db++) {
                int nextB = (actB == 1 && db > 0) ? 1 : 0;
                int tot = da + db + carry;
                if (tot % 10 == target) {
                    ans += dfs(idx + 1, tot / 10, nextA, nextB);
                }
            }
        }
        return memo[idx][carry][actA][actB] = ans;
    }

    public long countNoZeroPairs(long n) {
        digits.clear();
        while (n > 0) {
            digits.add((int)(n % 10));
            n /= 10;
        }
        memo = new Long[digits.size() + 1][2][2][2];
        return dfs(0, 0, 1, 1);
    }
}

var countNoZeroPairs = function(n) {
    const digits = [];
    let temp = BigInt(n);
    while (temp > 0n) {
        digits.push(Number(temp % 10n));
        temp /= 10n;
    }
    const memo = new Map();
    function dfs(idx, carry, actA, actB) {
        if (idx === digits.length) {
            return carry === 0 ? 1n : 0n;
        }
        const key = `${idx},${carry},${actA},${actB}`;
        if (memo.has(key)) return memo.get(key);
        const target = digits[idx];
        let ans = 0n;
        const minA = (actA && idx === 0) ? 1 : 0;
        const maxA = actA ? 9 : 0;
        const minB = (actB && idx === 0) ? 1 : 0;
        const maxB = actB ? 9 : 0;
        for (let da = minA; da <= maxA; da++) {
            const nextA = actA && (da > 0);
            for (let db = minB; db <= maxB; db++) {
                const nextB = actB && (db > 0);
                const tot = da + db + carry;
                if (tot % 10 === target) {
                    ans += dfs(idx + 1, Math.floor(tot / 10), nextA, nextB);
                }
            }
        }
        memo.set(key, ans);
        return ans;
    }
    return Number(dfs(0, 0, true, true));
};
